'use client';
import { useEffect, useState } from 'react';
import { useAuthStore } from '@/stores/auth-store';
import { api } from '@/lib/api-client'; /** * Restores the client session on app load by calling GET /auth/me. * With httpOnly cookie auth, the cookie is sent automatically — no * localStorage tokens involved. Marks the store hydrated either way so * `hasHydrated` gates (nav menus, admin gate) can render correctly. */
export function AuthHydration({ children }: { children?: React.ReactNode }) {
  const setUser = useAuthStore((s) => s.setUser);
  const setHydrated = useAuthStore((s) => s.setHydrated);
  const [done, setDone] = useState(false);
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const user = await api.get<any>('/auth/me');
        if (!cancelled) setUser(user);
      } catch {
        if (!cancelled) setHydrated(true);
      }
      if (!cancelled) setDone(true);
    })();
    return () => {
      cancelled = true;
    };
  }, [setUser, setHydrated]);
  return (
    <>
      {' '}
      {children} {/* Hidden marker for tests */}{' '}
      <span data-auth-hydrated={done ? 'true' : 'false'} hidden />{' '}
    </>
  );
}
